package dev.industrialtechnology.railway;
import net.minecraft.item.*;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.world.World;import net.minecraft.util.*;import net.minecraft.init.Blocks;
public final class ItemTrack extends Item {
 public final int kind;public ItemTrack(int k){kind=k;setUnlocalizedName("industrialtech.track_"+k);setTextureName("industrialtech:track_"+k);setCreativeTab(dev.industrialtechnology.core.ModRegistry.TAB);}
 @Override public boolean onItemUse(ItemStack stack,EntityPlayer player,World w,int x,int y,int z,int side,float a,float b,float c){if(side!=1)return false;y++;if(w.isRemote)return true;int facing=Math.floorMod((int)Math.floor(player.rotationYaw/90.0+.5)+1,4);RailPath path=new RailPath(x+.5,y+.125,z+.5,facing,kind==5?0:kind,0);if(!player.canPlayerEdit(x,y,z,side,stack)||!w.isAirBlock(x,y,z))return false;for(int branch=0;branch<(kind==4?2:1);branch++){RailPath p=new RailPath(x+.5,y+.125,z+.5,facing,kind==5?0:kind,branch);for(double s=0;s<=p.length;s+=.5){double[] v=p.point(s);int px=MathHelper.floor_double(v[0]),py=MathHelper.floor_double(v[1]),pz=MathHelper.floor_double(v[2]);if(!w.getChunkProvider().chunkExists(px>>4,pz>>4)){player.addChatMessage(new ChatComponentText("Load the full 16 m track footprint before placing it."));return false;}for(int h=0;h<5;h++)for(int width=-1;width<=1;width++){int qx=px+(facing%2==0?0:width),qz=pz+(facing%2==0?width:0);if(!player.canPlayerEdit(qx,py+h,qz,side,stack))return false;net.minecraft.block.Block block=w.getBlock(qx,py+h,qz);if(block!=RailwayRegistry.anchor&&!block.isReplaceable(w,qx,py+h,qz)&&block!=Blocks.air){player.addChatMessage(new ChatComponentText("Clear a 3 m wide, 5 m high track route first."));return false;}}}}w.setBlock(x,y,z,RailwayRegistry.anchor,kind,3);TileTrack t=(TileTrack)w.getTileEntity(x,y,z);t.shape=kind==5?0:kind;t.station=kind==5;t.facing=facing;t.markDirty();TrackWorld.remove(t);TrackWorld.add(t);w.markBlockForUpdate(x,y,z);if(!player.capabilities.isCreativeMode)stack.stackSize--;return true;}
 @Override public void addInformation(ItemStack s,EntityPlayer p,java.util.List text,boolean a){text.add(kind==1||kind==2?"90 degree curve, radius 16 m":"16 m segment; face its travel direction");text.add("Place on ground; endpoints join exactly.");text.add("Standard gauge 1.435 m; 3 m clearance");if(kind==4)text.add("Right click / redstone changes branch");}
}
